@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <li class="step-item @stepClass">
                @if (stepIndex < CurrentStep)
                {
                    <button class="step-button completed" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button @stepClass">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator { margin-bottom: 2rem; }
    .step-list { display: flex; list-style: none; padding: 0; margin: 0; justify-content: space-between; }
    .step-item { flex: 1; text-align: center; position: relative; }
    .step-item::after { content: ""; position: absolute; top: 1rem; left: 50%; width: 100%; height: 2px; background: #ddd; z-index: 0; }
    .step-item:last-child::after { display: none; }
    .step-item.completed::after { background: #28a745; }
    .step-button { display: inline-flex; flex-direction: column; align-items: center; gap: 0.5rem; background: none; border: none; cursor: default; padding: 0; z-index: 1; position: relative; }
    button.step-button { cursor: pointer; }
    .step-icon { width: 2rem; height: 2rem; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: bold; font-size: 0.875rem; }
    .step-item.completed .step-icon { background: #28a745; color: white; }
    .step-item.active .step-icon { background: #007bff; color: white; }
    .step-item.future .step-icon { background: #e9ecef; color: #6c757d; }
    .step-label { font-size: 0.75rem; white-space: nowrap; }
    .step-item.future .step-label { color: #6c757d; }
    .step-item.active .step-label { font-weight: bold; color: #007bff; }
</style>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private string GetStepClass(int index)
    {
        if (index < CurrentStep) return "completed";
        if (index == CurrentStep) return "active";
        return "future";
    }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" class="form-control" rows="2"
                  @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)">@Address</textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (ShowRemove)
        {
            <button class="btn btn-sm btn-danger" @onclick="OnRemove.InvokeAsync">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company *</label>
            <input type="text" class="form-control" value="@Company"
                   @oninput="e => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title"
                   @oninput="e => TitleChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => StartDateChanged.InvokeAsync(DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
