                   @oninput="e => CompanyChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" value="@Title"
                   @oninput="e => TitleChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => StartDateChanged.InvokeAsync(DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@IsCurrent"
                   @onchange="e => EndDateChanged.InvokeAsync(string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!))" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => IsCurrentChanged.InvokeAsync((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3"
                  @oninput="e => DescriptionChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)">@Description</textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
