    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }

    [Parameter] public EventCallback<string> CompanyChanged { get; set; }
    [Parameter] public EventCallback<string> TitleChanged { get; set; }
    [Parameter] public EventCallback<DateTime> StartDateChanged { get; set; }
    [Parameter] public EventCallback<DateTime?> EndDateChanged { get; set; }
    [Parameter] public EventCallback<bool> IsCurrentChanged { get; set; }
    [Parameter] public EventCallback<string> DescriptionChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <li class="step-item @stepClass">
                @if (stepIndex < CurrentStep)
                {
                    <button class="step-button completed" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button @stepClass">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@Steps[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator { margin-bottom: 2rem; }
    .step-list { display: flex; list-style: none; padding: 0; margin: 0; justify-content: space-between; }
    .step-item { flex: 1; text-align: center; position: relative; }
    .step-item::after { content: ""; position: absolute; top: 1rem; left: 50%; width: 100%; height: 2px; background: #ddd; z-index: 0; }
    .step-item:last-child::after { display: none; }
    .step-item.completed::after { background: #28a745; }
    .step-button { display: inline-flex; flex-direction: column; align-items: center; gap: 0.5rem; background: none; border: none; cursor: default; padding: 0; z-index: 1; position: relative; }
    button.step-button { cursor: pointer; }
    .step-icon { width: 2rem; height: 2rem; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: bold; font-size: 0.875rem; }
    .step-item.completed .step-icon { background: #28a745; color: white; }
    .step-item.active .step-icon { background: #007bff; color: white; }
    .step-item.future .step-icon { background: #e9ecef; color: #6c757d; }
    .step-label { font-size: 0.75rem; white-space: nowrap; }
    .step-item.future .step-label { color: #6c757d; }
    .step-item.active .step-label { font-weight: bold; color: #007bff; }
</style>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private string GetStepClass(int index)
    {
        if (index < CurrentStep) return "completed";
        if (index == CurrentStep) return "active";
        return "future";
    }
}

