@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="personal-info-step">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @oninput="e => FullNameChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        @if (!string.IsNullOrEmpty(EmailError))
        {
            <span class="field-error">@EmailError</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" class="form-control" rows="2"
                  @oninput="e => AddressChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)">@Address</textarea>
    </div>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="reference-form">
    <h5>Reference @(Index + 1)</h5>

    <div class="form-row">
        <div class="form-group">
            <label>Name *</label>
            <input type="text" class="form-control" value="@Name"
                   @oninput="e => NameChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Relationship *</label>
            <input type="text" class="form-control" value="@Relationship"
                   @oninput="e => RelationshipChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Email"
                   @oninput="e => EmailChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
        <div class="form-group">
            <label>Phone *</label>
            <input type="tel" class="form-control" value="@Phone"
                   @oninput="e => PhoneChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)" />
        </div>
    </div>

    @if (ShowRemove)
    {
        <button class="btn btn-sm btn-danger" @onclick="OnRemove.InvokeAsync">Remove</button>
    }
