    [Parameter] public EventCallback<string> NameChanged { get; set; }
    [Parameter] public EventCallback<string> RelationshipChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

arguments.file_text:
@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="work-history-step">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <WorkEntryForm Index="index"
                       Company="@entry.Company"
                       Title="@entry.Title"
                       StartDate="@entry.StartDate"
                       EndDate="@entry.EndDate"
                       IsCurrent="@entry.IsCurrent"
                       Description="@entry.Description"
                       ShowRemove="@(Entries.Count > 1)"
                       CompanyChanged="e => UpdateEntry(index, entry with { Company = e })"
                       TitleChanged="e => UpdateEntry(index, entry with { Title = e })"
                       StartDateChanged="e => UpdateEntry(index, entry with { StartDate = e })"
                       EndDateChanged="e => UpdateEntry(index, entry with { EndDate = e })"
                       IsCurrentChanged="e => UpdateEntry(index, entry with { IsCurrent = e, EndDate = e ? null : entry.EndDate })"
                       DescriptionChanged="e => UpdateEntry(index, entry with { Description = e })"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-primary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
        EntriesChanged.InvokeAsync(Entries);
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        EntriesChanged.InvokeAsync(Entries);
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        EntriesChanged.InvokeAsync(Entries);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="references-step">
    <h3>References</h3>
    <p class="text-muted">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <ReferenceForm Index="index"
                       Name="@reference.Name"
                       Relationship="@reference.Relationship"
                       Email="@reference.Email"
                       Phone="@reference.Phone"
                       ShowRemove="@(References.Count > 2)"
                       NameChanged="e => UpdateRef(index, reference with { Name = e })"
                       RelationshipChanged="e => UpdateRef(index, reference with { Relationship = e })"
                       EmailChanged="e => UpdateRef(index, reference with { Email = e })"
                       PhoneChanged="e => UpdateRef(index, reference with { Phone = e })"
                       OnRemove="() => RemoveRef(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-outline-primary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ValidationError))
    {
        <div class="validation-error">@ValidationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> ReferencesChanged { get; set; }
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private void UpdateRef(int index, ReferenceModel updated)
    {
        References[index] = updated;
        ReferencesChanged.InvokeAsync(References);
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
            ReferencesChanged.InvokeAsync(References);
        }
    }

    private void RemoveRef(int index)
    {
        References.RemoveAt(index);
        ReferencesChanged.InvokeAsync(References);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply

<div class="cover-letter-step">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below:</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="2000"
                  @oninput="e => CoverLetterChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty)">@CoverLetter</textarea>
        <div class="char-count @(CoverLetter.Length > 1800 ? "warning" : "")">
            @CoverLetter.Length / 2000 characters
        </div>
    </div>

    <div class="step-actions">
        <button class="btn btn-secondary" @onclick="OnBack.InvokeAsync">Back</button>
        <button class="btn btn-primary" @onclick="OnNext.InvokeAsync">Next</button>
    </div>
</div>

<style>
    .cover-letter-textarea { font-family: inherit; resize: vertical; min-height: 200px; }
    .char-count { text-align: right; font-size: 0.875rem; color: #6c757d; margin-top: 0.25rem; }
    .char-count.warning { color: #dc3545; }
</style>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
}

@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply
@using static sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply.WorkHistoryStep
@using static sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply.ReferencesStep

<div class="review-step">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button class="btn btn-sm btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="work-review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="entry-description">@entry.Description</p>
                    }
                </div>
            }
        </section>

