arguments.file_text:
@page "/apply"
@namespace sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply
@using sv_ceaee8b3402a4cdbb68f44653e5e35a4.Models
@using sv_ceaee8b3402a4cdbb68f44653e5e35a4.Services
@using static sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply.WorkHistoryStep
@using static sv_ceaee8b3402a4cdbb68f44653e5e35a4.Components.Pages.Apply.ReferencesStep
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                              ValidationError="@_validationError" EmailError="@_emailError" IsValidating="@_isValidating"
                              FullNameChanged="e => _fullName = e"
                              EmailChanged="e => { _email = e; _emailError = null; }"
                              PhoneChanged="e => _phone = e"
                              AddressChanged="e => _address = e"
                              OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="_workEntries" EntriesChanged="e => _workEntries = e"
                             ValidationError="@_validationError"
                             OnBack="GoBack" OnNext="HandleWorkHistoryNext" />
            break;
        case 2:
            <ReferencesStep References="_references" ReferencesChanged="e => _references = e"
                            ValidationError="@_validationError"
                            OnBack="GoBack" OnNext="HandleReferencesNext" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="e => _coverLetter = e"
                             OnBack="GoBack" OnNext="() => GoForward()" />
            break;
        case 4:
            <ReviewStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                        WorkEntries="_workEntries" References="_references" CoverLetter="@_coverLetter"
                        IsSubmitting="_isSubmitting" IsSubmitted="_isSubmitted"
                        ApplicationId="_applicationId" SubmissionError="@_submissionError"
                        OnBack="GoBack" OnSubmit="HandleSubmit" OnEditSection="GoToStep" />
            break;
    }
</div>

<style>
    .apply-page { max-width: 800px; margin: 0 auto; padding: 2rem 1rem; }
    .form-group { margin-bottom: 1rem; }
    .form-group label { display: block; font-weight: 600; margin-bottom: 0.25rem; }
    .form-control { width: 100%; padding: 0.5rem; border: 1px solid #ced4da; border-radius: 0.25rem; font-size: 1rem; }
    .form-control:focus { outline: none; border-color: #80bdff; box-shadow: 0 0 0 0.2rem rgba(0,123,255,.25); }
    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
    .step-actions { display: flex; justify-content: space-between; margin-top: 1.5rem; padding-top: 1rem; border-top: 1px solid #e9ecef; }
    .btn { padding: 0.5rem 1.5rem; border: none; border-radius: 0.25rem; font-size: 1rem; cursor: pointer; text-decoration: none; }
    .btn:disabled { opacity: 0.6; cursor: not-allowed; }
    .btn-primary { background: #007bff; color: white; }
    .btn-primary:hover:not(:disabled) { background: #0056b3; }
    .btn-secondary { background: #6c757d; color: white; }
    .btn-secondary:hover { background: #545b62; }
    .btn-success { background: #28a745; color: white; }
    .btn-success:hover:not(:disabled) { background: #1e7e34; }
    .btn-danger { background: #dc3545; color: white; }
    .btn-danger:hover { background: #c82333; }
    .btn-outline-primary { background: transparent; border: 1px solid #007bff; color: #007bff; }
    .btn-outline-primary:hover { background: #007bff; color: white; }
    .btn-link { background: none; border: none; color: #007bff; padding: 0; font-size: 0.875rem; }
    .btn-sm { padding: 0.25rem 0.75rem; font-size: 0.875rem; }
    .btn-lg { padding: 0.75rem 2rem; font-size: 1.1rem; }
    .validation-error { color: #dc3545; margin-top: 0.5rem; padding: 0.5rem; background: #f8d7da; border-radius: 0.25rem; }
    .field-error { color: #dc3545; font-size: 0.875rem; }
    .text-muted { color: #6c757d; }
    .checkbox-label { display: inline-flex; align-items: center; gap: 0.5rem; font-weight: normal; margin-top: 0.25rem; }
    .work-entry-form, .reference-form { border: 1px solid #e9ecef; border-radius: 0.5rem; padding: 1rem; margin-bottom: 1rem; }
    .entry-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.75rem; }
    .entry-header h5 { margin: 0; }
</style>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private bool _isSubmitting;
    private bool _isSubmitted;
    private int? _applicationId;
    private string? _submissionError;

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _validationError = null;
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        _validationError = null;
        if (_currentStep > 0) _currentStep--;
    }

    private void GoForward()
    {
        _validationError = null;
        if (_currentStep < 4) _currentStep++;
    }

    private async Task HandlePersonalInfoNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _validationError = "Please fill in all required fields.";
            return;
        }

        _isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            if (!emailValid)
            {
                _emailError = "Please enter a valid email address.";
                _isValidating = false;
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        GoForward();
    }

    private void HandleWorkHistoryNext()
    {
        _validationError = null;
        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Please fill in the company and job title for all positions.";
                return;
            }
        }
        GoForward();
    }

    private void HandleReferencesNext()
    {
        _validationError = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "Please fill in all fields for each reference.";
                return;
            }
        }
        GoForward();
    }

    private async Task HandleSubmit()
    {
        _isSubmitting = true;
        _submissionError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
                )).ToList()),
                _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _isSubmitted = true;
        }
        catch (Exception ex)
        {
            _submissionError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

